// Konstruktor new URL(String) jest ODRADZANY dla dowolnych, niezaufanych
// stringow - nie waliduje w pelni skladni zgodnie z RFC, a od Javy 20
// czesc jego przeciazen jest formalnie oznaczona jako @Deprecated.
// Zalecany wzorzec: najpierw zbuduj i zwaliduj URI, dopiero potem
// (jesli faktycznie potrzebujesz sie polaczyc) zamien je na URL:

URI uri = new URI("https://example.com/path");
URL url = uri.toURL();

// URI w konstruktorze RZUCA wyjatek (URISyntaxException) przy blednej
// skladni - szybciej wykrywamy problem niz przy "cichszym" zachowaniu
// starego URL(String).

URI uri = new URI("https://example.com:8443/search?q=java&lang=pl#results");
URL url = uri.toURL();

url.getProtocol();  // https
url.getHost();      // example.com
url.getPort();      // 8443 (jawnie podany)
url.getDefaultPort(); // 443 (domyslny dla https)
url.getPath();      // /search
url.getQuery();     // q=java&lang=pl
url.getRef();       // results
url.getFile();      // /search?q=java&lang=pl (path + query)
url.getAuthority();  // example.com:8443

// URI ma analogiczne gettery: getScheme(), getHost(), getPort(),
// getPath(), getQuery(), getFragment().
